// Check for VM artifacts
BOOL IsVM() {
    // Check CPUID
    int cpuinfo[4];
    __cpuid(cpuinfo, 1);
    if ((cpuinfo[2] >> 31) & 1) return TRUE; // Hypervisor present

    // Check common VM files
    if (GetFileAttributesA("C:\\Windows\\System32\\drivers\\VBoxGuest.sys") != INVALID_FILE_ATTRIBUTES)
        return TRUE;
    if (GetFileAttributesA("C:\\Windows\\System32\\drivers\\vmhgfs.sys") != INVALID_FILE_ATTRIBUTES)
        return TRUE;

    // Check registry for VM indicators
    HKEY hKey;
    if (RegOpenKeyExA(HKEY_LOCAL_MACHINE, "SYSTEM\\CurrentControlSet\\Services\\Disk\\Enum", 
                      0, KEY_READ, &hKey) == ERROR_SUCCESS) {
        char buf[256];
        DWORD size = sizeof(buf);
        RegQueryValueExA(hKey, "0", NULL, NULL, (LPBYTE)buf, &size);
        if (strstr(buf, "VBOX") || strstr(buf, "VMware") || strstr(buf, "QEMU"))
            return TRUE;
    }
    return FALSE;
}

// RC4 decryption
void RC4Decrypt(BYTE* key, BYTE* data, size_t len) {
    BYTE S[256];
    for (int i = 0; i < 256; i++) S[i] = i;

    int j = 0;
    for (int i = 0; i < 256; i++) {
        j = (j + S[i] + key[i % keyLen]) % 256;
        BYTE tmp = S[i]; S[i] = S[j]; S[j] = tmp;
    }

    int i = 0, j = 0;
    for (size_t k = 0; k < len; k++) {
        i = (i + 1) % 256;
        j = (j + S[i]) % 256;
        BYTE tmp = S[i]; S[i] = S[j]; S[j] = tmp;
        data[k] ^= S[(S[i] + S[j]) % 256];
    }
}

